-- Check if using sensortrack gives same or different vehicles than alerttime
WITH alert_ranked AS (
    SELECT vehsenseref, ROW_NUMBER() OVER (PARTITION BY vehsenseref ORDER BY alerttime DESC) as rn FROM sensordata
),
track_ranked AS (
    SELECT vehsenseref, ROW_NUMBER() OVER (PARTITION BY vehsenseref ORDER BY sensortrack DESC) as rn FROM sensordata
)
SELECT COUNT(*) FROM (
    SELECT ar.vehsenseref FROM alert_ranked ar WHERE ar.rn = 1
    EXCEPT
    SELECT tr.vehsenseref FROM track_ranked tr WHERE tr.rn = 1
) diff;
